"""Vault resource for managing credential vault connections and items."""

from __future__ import annotations

from urllib.parse import quote

from tinyfish._utils.client import BaseAsyncAPIClient, BaseSyncAPIClient
from tinyfish._utils.resource import BaseAsyncAPIResource, BaseSyncAPIResource

from .types import (
    VaultConnectResponse,
    VaultDisconnectResponse,
    VaultListConnectionsResponse,
    VaultListItemsResponse,
    VaultSyncItemsResponse,
)


class VaultConnectionsResource(BaseSyncAPIResource):
    """Manage vault provider connections (sync)."""

    def connect_1password(self, *, token: str) -> VaultConnectResponse:
        """Connect a 1Password vault.

        Args:
            token: 1Password service account token (starts with "ops_").

        Returns:
            VaultConnectResponse with connection ID and discovered items.

        Raises:
            BadRequestError: Invalid token format.
            AuthenticationError: Invalid API key.
        """
        body = {"provider": "1password", "token": token}
        return self._post("/v1/vault/connections", json=body, cast_to=VaultConnectResponse)

    def connect_bitwarden(
        self,
        *,
        client_id: str,
        client_secret: str,
        master_password: str,
        server_url: str | None = None,
    ) -> VaultConnectResponse:
        """Connect a Bitwarden vault.

        Args:
            client_id: Bitwarden API client ID.
            client_secret: Bitwarden API client secret.
            master_password: Bitwarden master password.
            server_url: Custom Bitwarden server URL (for self-hosted instances).

        Returns:
            VaultConnectResponse with connection ID and discovered items.

        Raises:
            BadRequestError: Invalid credentials format.
            AuthenticationError: Invalid API key.
        """
        body: dict[str, str] = {
            "provider": "bitwarden",
            "clientId": client_id,
            "clientSecret": client_secret,
            "masterPassword": master_password,
        }
        if server_url is not None:
            body["serverUrl"] = server_url
        return self._post("/v1/vault/connections", json=body, cast_to=VaultConnectResponse)

    def list(self) -> VaultListConnectionsResponse:
        """List all vault connections.

        Returns:
            VaultListConnectionsResponse with list of connections.

        Raises:
            AuthenticationError: Invalid API key.
        """
        return self._get("/v1/vault/connections", cast_to=VaultListConnectionsResponse)

    def disconnect(self, connection_id: str) -> VaultDisconnectResponse:
        """Disconnect a vault provider.

        Args:
            connection_id: The connection ID to disconnect.

        Returns:
            VaultDisconnectResponse confirming disconnection.

        Raises:
            ValueError: connection_id is empty or whitespace.
            BadRequestError: Invalid connection ID format.
            NotFoundError: Connection not found.
        """
        if not connection_id or not connection_id.strip():
            raise ValueError("connection_id must be a non-empty string")
        encoded_id = quote(connection_id, safe="")
        return self._delete(
            f"/v1/vault/connections/{encoded_id}",
            cast_to=VaultDisconnectResponse,
        )


class AsyncVaultConnectionsResource(BaseAsyncAPIResource):
    """Manage vault provider connections (async)."""

    async def connect_1password(self, *, token: str) -> VaultConnectResponse:
        """Connect a 1Password vault."""
        body = {"provider": "1password", "token": token}
        return await self._post("/v1/vault/connections", json=body, cast_to=VaultConnectResponse)

    async def connect_bitwarden(
        self,
        *,
        client_id: str,
        client_secret: str,
        master_password: str,
        server_url: str | None = None,
    ) -> VaultConnectResponse:
        """Connect a Bitwarden vault."""
        body: dict[str, str] = {
            "provider": "bitwarden",
            "clientId": client_id,
            "clientSecret": client_secret,
            "masterPassword": master_password,
        }
        if server_url is not None:
            body["serverUrl"] = server_url
        return await self._post("/v1/vault/connections", json=body, cast_to=VaultConnectResponse)

    async def list(self) -> VaultListConnectionsResponse:
        """List all vault connections."""
        return await self._get("/v1/vault/connections", cast_to=VaultListConnectionsResponse)

    async def disconnect(self, connection_id: str) -> VaultDisconnectResponse:
        """Disconnect a vault provider."""
        if not connection_id or not connection_id.strip():
            raise ValueError("connection_id must be a non-empty string")
        encoded_id = quote(connection_id, safe="")
        return await self._delete(
            f"/v1/vault/connections/{encoded_id}",
            cast_to=VaultDisconnectResponse,
        )


class VaultItemsResource(BaseSyncAPIResource):
    """Manage vault items (sync)."""

    def list(self) -> VaultListItemsResponse:
        """List all vault items across all connections.

        Returns:
            VaultListItemsResponse with list of items.

        Raises:
            NotFoundError: No vault connections exist.
            AuthenticationError: Invalid API key.
        """
        return self._get("/v1/vault/items", cast_to=VaultListItemsResponse)

    def sync(self) -> VaultSyncItemsResponse:
        """Sync items from all connected vault providers.

        Returns:
            VaultSyncItemsResponse with updated items and sync summary.

        Raises:
            NotFoundError: No vault connections exist.
            AuthenticationError: Invalid API key.
        """
        return self._post("/v1/vault/items/sync", json=None, cast_to=VaultSyncItemsResponse)


class AsyncVaultItemsResource(BaseAsyncAPIResource):
    """Manage vault items (async)."""

    async def list(self) -> VaultListItemsResponse:
        """List all vault items across all connections."""
        return await self._get("/v1/vault/items", cast_to=VaultListItemsResponse)

    async def sync(self) -> VaultSyncItemsResponse:
        """Sync items from all connected vault providers."""
        return await self._post("/v1/vault/items/sync", json=None, cast_to=VaultSyncItemsResponse)


class VaultResource(BaseSyncAPIResource):
    """Vault API namespace (sync)."""

    connections: VaultConnectionsResource
    items: VaultItemsResource

    def __init__(self, client: BaseSyncAPIClient) -> None:
        super().__init__(client)
        self.connections = VaultConnectionsResource(client)
        self.items = VaultItemsResource(client)


class AsyncVaultResource(BaseAsyncAPIResource):
    """Vault API namespace (async)."""

    connections: AsyncVaultConnectionsResource
    items: AsyncVaultItemsResource

    def __init__(self, client: BaseAsyncAPIClient) -> None:
        super().__init__(client)
        self.connections = AsyncVaultConnectionsResource(client)
        self.items = AsyncVaultItemsResource(client)
